// Power Settings Widget — mirrors data/index.html menu-3 (Protection Settings).
// Stores pSettings as SHARED attribute; polls CLIENT scope to confirm device echoed.

var DC_MIN = 0.0, DCMAX = 30;
var OCMIN = 0.01, OCMAX = 50;
var LVMIN = 150, LVMAX = 250;
var OVMIN = 200, OVMAX = 290;

// === HELP CATALOG (generated from data/help_en.json - do not edit by hand) ===
// Regenerate with: python3 tools/sync_widget_help.py
var HELP_CATALOG = {"_base":"https://www.eviqtech.com/manual/swigo-supersmart/","power.dryrunCurrent":{"t":"Dryrun Current","s":"The device stops if current stays below this value for 4 to 7 seconds.<br>Example: a pump running with no water draws about 20% less than its normal current.","l":"#protection-settings"},"power.dryrunRestart":{"t":"Restart After Dryrun","s":"Tick this to let the device try again after a dryrun fault, and set the retry time below.","l":"#protection-settings"},"power.dryrunRetry":{"t":"Dryrun Retry","s":"Delay in minutes before the device retries after a dryrun fault.","l":"#protection-settings"},"power.protectionOnly":{"t":"Protection Only","s":"Choose Yes if this unit sits before a master switch and only protects the load instead of controlling it.","l":"#protection-settings"},"power.thresholdCurrent":{"t":"Threshold Current","s":"For a protection-only device, dryrun detection starts only once current has reached this value.","l":"#protection-settings"},"power.overcurrent":{"t":"Overload Current","s":"The device stops if current stays above this value for 4 to 7 seconds.<br>Example: a seized shaft or damaged winding draws about 20% more than the normal current.","l":"#protection-settings:~:text=Overload%20Protection%20(Over%2DCurrent)"},"power.overcurrentRestart":{"t":"Restart After Overload","s":"Tick this to let the device try again after an overload fault, and set the retry time below."},"power.overcurrentRetry":{"t":"Overload Retry","s":"Delay in minutes before the device retries after an overload fault."},"power.lowVoltage":{"t":"Low Voltage Limit","s":"The device will not start, and stops while running, if voltage stays below this value for more than 7 seconds.<br>Running a motor on low voltage makes it draw more current and heat up.","l":"#voltage-protection"},"power.lowVoltageRestart":{"t":"Restart After Low Voltage","s":"Tick this to let the device try again after a low voltage fault.<br>On 3-phase units this setting also covers phase failure and phase sequence reversal."},"power.lowVoltageRetry":{"t":"Low Voltage Retry","s":"Delay in minutes before the device retries after a low voltage fault.<br>Retries happen only within the scheduled time; if the retry falls after it, the device stays off."},"power.highVoltage":{"t":"High Voltage Limit","s":"The device stops if voltage goes above this value.<br>Sustained high voltage damages motor insulation and capacitors over time.","l":"#voltage-protection"},"power.highVoltageRestart":{"t":"Restart After High Voltage","s":"Tick this to let the device try again after a high voltage fault."},"power.highVoltageRetry":{"t":"High Voltage Retry","s":"Delay in minutes before the device retries after a high voltage fault.<br>Retries happen only within the scheduled time; if the retry falls after it, the device stays off."},"power.powerResumeRestart":{"t":"Restart After Power Resumes","s":"Tick this to let the device start again by itself once mains power comes back during a run or a schedule.","l":"#protection-settings:~:text=Additional%20Protection%20Settings"},"power.restartDelay":{"t":"Restart Delay","s":"Minutes to wait before restarting after power resumes.<br>The delay protects the load from the voltage spikes that often follow a power cut.","l":"#protection-settings:~:text=Additional%20Protection%20Settings"},"power.maxRunDuration":{"t":"Max Run Duration","s":"Longest the device may run continuously before it must take a break. Valid range is 1 to 1440 minutes.","l":"#protection-settings:~:text=Additional%20Protection%20Settings"},"power.breakTime":{"t":"Break Time","s":"How long the device stays off after reaching the maximum run duration. Valid range is 1 to 1440 minutes.","l":"#protection-settings:~:text=Additional%20Protection%20Settings"}};
// === END HELP CATALOG ===

// The same help texts the device portal shows. Carried here because the widget
// cannot reach the device's own /help_en.json - the device is on a LAN and may
// be offline - so the catalog above is generated into this file instead.
function helpEntry(id) { return HELP_CATALOG && HELP_CATALOG[id]; }

// `l` is a path relative to the catalog's _base, so the manual's address is
// configured in one place; an absolute URL is honoured as an escape hatch.
function helpLink(entry) {
    if (!entry || !entry.l) return null;
    if (/^https?:\/\//i.test(entry.l)) return entry.l;
    var base = HELP_CATALOG._base;
    if (!base) return null;
    return base.replace(/\/+$/, '') + '/' + String(entry.l).replace(/^\/+/, '');
}

// Document-level listener, live only while a panel is open, so a click anywhere
// else dismisses it. Removed on close (and on destroy) rather than left bound.
var helpOutsideHandler = null;

function closeHelpPanel() {
    self.ctx.$container.find('.sch-help-panel').remove();
    if (helpOutsideHandler) {
        $(document).off('mousedown touchstart', helpOutsideHandler);
        helpOutsideHandler = null;
    }
}

// Click the icon to open, click it again (or another one) to close. The panel
// is inserted right after the icon - as a grid child spanning every column - so
// it needs no positioning maths and cannot end up off-screen.
function toggleHelpPanel($icon, id) {
    var $open = self.ctx.$container.find('.sch-help-panel');
    var sameIcon = $open.length && $open.attr('data-help-id') === id && $icon.next('.sch-help-panel').length;
    closeHelpPanel();
    if (sameIcon) return;
    var entry = helpEntry(id);
    if (!entry) return;
    var link = helpLink(entry);
    $icon.after('<div class="sch-help-panel" data-help-id="' + id + '">' +
        '<div class="sch-help-title">' + (entry.t || '') + '</div>' +
        '<div class="sch-help-body">' + (entry.s || '') + '</div>' +
        (link ? '<a class="sch-help-link" href="' + link + '" target="_blank" rel="noopener">Learn more</a>' : '') +
        '</div>');

    // Clicks inside the panel are left alone (the Learn more link, text
    // selection); a click on any help icon is left to the icon's own handler,
    // which toggles. Everything else closes the panel.
    helpOutsideHandler = function(ev) {
        var $target = $(ev.target);
        if ($target.closest('.sch-help-panel').length) return;
        if ($target.closest('.help-i').length) return;
        closeHelpPanel();
    };
    $(document).on('mousedown touchstart', helpOutsideHandler);
}

var loadRetryCount = 0;
var maxRetries = 5;
var sessionHealthTimer = null;
var lastSuccessfulLoad = 0;
var visibilityHandler = null;
var SESSION_HEALTH_INTERVAL = 60000;
var SESSION_STALE_THRESHOLD = 120000;

self.onInit = function() {
    self.ctx.powerData = null;
    self.ctx.cachedEntity = null;
    // Delegated: the rows are static markup, so one binding covers all icons.
    self.ctx.$container.on('click', '.help-i', function(e) {
        e.stopPropagation();
        e.preventDefault();
        toggleHelpPanel($(this), $(this).attr('data-help'));
    });
    initializeUI();
    setTimeout(function() { loadAllData(); }, 800);
    startSessionKeepAlive();
};

function initializeUI() {
    var $c = self.ctx.$container;
    // Restart-after-fault checkboxes gate their retry-minutes input.
    var pairs = [['pw_res-dr','pw_drMin'], ['pw_res-ol','pw_orMin'], ['pw_res-lv','pw_lVolMin'], ['pw_res-hv','pw_hVolMin'], ['pw_res-i-1','pw_stDly']];
    pairs.forEach(function(p) {
        $c.find('#' + p[0]).on('change', function() {
            var enabled = this.checked;
            $c.find('#' + p[1]).prop('disabled', !enabled);
            if (!enabled) $c.find('#' + p[1]).val('');
        });
    });
    // "Used for protection only" radio gates threshold-current input.
    $c.find('input[name="pw_isSlave"]').on('change', function() {
        var v = $c.find('input[name="pw_isSlave"]:checked').val();
        $c.find('#pw_thCur').prop('disabled', v !== '1');
        if (v !== '1') $c.find('#pw_thCur').val('');
    });
    $c.find('#btnSavePower').on('click', function() { savePowerSettings(); });
}

function setChecked($c, id, val) {
    $c.find('#' + id).prop('checked', val == 1 || val === '1' || val === true);
}

function setRadio($c, name, value) {
    if (value === undefined || value === null) return;
    var $r = $c.find('input[name="' + name + '"][value="' + String(value) + '"]');
    if ($r.length) $r.prop('checked', true);
}

function applyPowerToForm(p) {
    var $c = self.ctx.$container;
    if (p.drCur !== undefined) $c.find('#pw_drCur').val(p.drCur);
    if (p.thCur !== undefined) $c.find('#pw_thCur').val(p.thCur);
    if (p.orCur !== undefined) $c.find('#pw_orCur').val(p.orCur);
    if (p.lVol !== undefined) $c.find('#pw_lVol').val(p.lVol);
    if (p.hVol !== undefined) $c.find('#pw_hVol').val(p.hVol);
    if (p.drMin !== undefined) $c.find('#pw_drMin').val(p.drMin);
    if (p.orMin !== undefined) $c.find('#pw_orMin').val(p.orMin);
    if (p.lVolMin !== undefined) $c.find('#pw_lVolMin').val(p.lVolMin);
    if (p.hVolMin !== undefined) $c.find('#pw_hVolMin').val(p.hVolMin);
    if (p.stDly !== undefined) $c.find('#pw_stDly').val(p.stDly);
    if (p.mR !== undefined) $c.find('#pw_mR').val(p.mR);
    if (p.bT !== undefined) $c.find('#pw_bT').val(p.bT);

    setChecked($c, 'pw_res-i-1', p.isRst);
    setChecked($c, 'pw_res-dr', p.isRstDr);
    setChecked($c, 'pw_res-ol', p.isRstOl);
    setChecked($c, 'pw_res-lv', p.isRstLv);
    setChecked($c, 'pw_res-hv', p.isRstHv);

    $c.find('#pw_stDly').prop('disabled', !(p.isRst == 1 || p.isRst === '1'));
    $c.find('#pw_drMin').prop('disabled', !(p.isRstDr == 1 || p.isRstDr === '1'));
    $c.find('#pw_orMin').prop('disabled', !(p.isRstOl == 1 || p.isRstOl === '1'));
    $c.find('#pw_lVolMin').prop('disabled', !(p.isRstLv == 1 || p.isRstLv === '1'));
    $c.find('#pw_hVolMin').prop('disabled', !(p.isRstHv == 1 || p.isRstHv === '1'));

    setRadio($c, 'pw_isSlave', p.isSlave);
    $c.find('#pw_thCur').prop('disabled', !(p.isSlave == 1 || p.isSlave === '1'));
}

function buildPayload() {
    var $c = self.ctx.$container;
    var isRstDr = $c.find('#pw_res-dr').prop('checked') ? '1' : '0';
    var isRstOl = $c.find('#pw_res-ol').prop('checked') ? '1' : '0';
    var isRstLv = $c.find('#pw_res-lv').prop('checked') ? '1' : '0';
    var isRstHv = $c.find('#pw_res-hv').prop('checked') ? '1' : '0';
    var isRst = $c.find('#pw_res-i-1').prop('checked') ? '1' : '0';
    var isSlave = $c.find('input[name="pw_isSlave"]:checked').val() || '0';

    return {
        drCur: parseFloat($c.find('#pw_drCur').val()),
        thCur: parseFloat($c.find('#pw_thCur').val()) || 0,
        orCur: parseFloat($c.find('#pw_orCur').val()),
        lVol: parseFloat($c.find('#pw_lVol').val()),
        hVol: parseFloat($c.find('#pw_hVol').val()),
        drMin: parseInt($c.find('#pw_drMin').val(), 10) || 0,
        orMin: parseInt($c.find('#pw_orMin').val(), 10) || 0,
        lVolMin: parseInt($c.find('#pw_lVolMin').val(), 10) || 0,
        hVolMin: parseInt($c.find('#pw_hVolMin').val(), 10) || 0,
        stDly: parseInt($c.find('#pw_stDly').val(), 10) || 0,
        mR: parseInt($c.find('#pw_mR').val(), 10) || 0,
        bT: parseInt($c.find('#pw_bT').val(), 10) || 0,
        isRst: isRst,
        isRstDr: isRstDr,
        isRstOl: isRstOl,
        isRstLv: isRstLv,
        isRstHv: isRstHv,
        isSlave: isSlave
    };
}

function validatePayload(p) {
    if (isNaN(p.drCur) || p.drCur < DC_MIN || p.drCur > DCMAX) return 'Dry run current must be between ' + DC_MIN + ' and ' + DCMAX;
    if (isNaN(p.thCur) || p.thCur < DC_MIN || p.thCur > DCMAX) return 'Dry run threshold must be between ' + DC_MIN + ' and ' + DCMAX;
    if (p.isSlave === '1' && p.thCur >= p.drCur) return 'Dry run threshold must be less than Dry run current';
    if (isNaN(p.orCur) || p.orCur < OCMIN || p.orCur > OCMAX) return 'Overload current must be between ' + OCMIN + ' and ' + OCMAX;
    if (isNaN(p.lVol) || p.lVol < LVMIN || p.lVol > LVMAX) return 'Low voltage must be between ' + LVMIN + ' and ' + LVMAX;
    if (isNaN(p.hVol) || p.hVol < OVMIN || p.hVol > OVMAX) return 'High voltage must be between ' + OVMIN + ' and ' + OVMAX;
    if ((p.isRstDr === '1' && p.drMin == 0) ||
        (p.isRstOl === '1' && p.orMin == 0) ||
        (p.isRstLv === '1' && p.lVolMin == 0) ||
        (p.isRstHv === '1' && p.hVolMin == 0)) {
        return 'Restart delay after fault must be at least 1 minute';
    }
    if (p.stDly > 30) return 'Restart delay must be between 0 and 30 minutes';
    if (p.mR > 1440 || p.bT > 1440) return 'Max-run and break time must not exceed 1440 minutes';
    return null;
}

function savePowerSettings() {
    showValidation('');
    var payload = buildPayload();
    var err = validatePayload(payload);
    if (err) { showValidation(err); return; }
    saveSharedAttr('pSettings', payload, function(e) { if (e) showValidation(e); });
}

function showValidation(msg) {
    self.ctx.$container.find('#pwValidation').text(msg || '');
}

function saveSharedAttr(key, payload, errCb) {
    getTargetEntityId(function(targetEntityId) {
        if (!targetEntityId || !targetEntityId.id) {
            errCb('No target device found.');
            return;
        }
        showStatus('pending', 'Sending ' + key + ' to device...');
        // Capture the current pSetErr baseline so a stale rejection from a previous
        // save is ignored; only an error reported AFTER this save counts.
        self.ctx.attributeService.getEntityAttributes(targetEntityId, 'CLIENT_SCOPE', ['pSetErr']).subscribe(
            function(attrs) {
                var baseErrTs = 0, baseErrVal = null;
                for (var i = 0; attrs && i < attrs.length; i++) {
                    var k = attrs[i].key !== undefined ? attrs[i].key : attrs[i].attributeKey;
                    if (k === 'pSetErr') { baseErrTs = attrs[i].lastUpdateTs || 0; baseErrVal = attrs[i].value; }
                }
                sendSharedAttr(key, payload, targetEntityId, baseErrTs, baseErrVal);
            },
            function() { sendSharedAttr(key, payload, targetEntityId, 0, null); }
        );
    });
}

function sendSharedAttr(key, payload, targetEntityId, baseErrTs, baseErrVal) {
    var jsonValue = JSON.stringify(payload);
    var attributes = [{ key: key, value: jsonValue }];
    self.ctx.attributeService.saveEntityAttributes(
        targetEntityId, 'SHARED_SCOPE', attributes
    ).subscribe(
        function() { pollForEcho(key, payload, targetEntityId, baseErrTs, baseErrVal); },
        function(error) {
            showStatus('failed', 'Failed to send ' + key + ': ' + (error.message || error.statusText || 'unknown'));
        }
    );
}

// Compare only the keys the widget sent. Echo may carry extra fields (is3Ph,
// floatRelayadded, etc.) which we ignore.
function matchesPayload(expected, echo) {
    if (!echo || typeof echo !== 'object') return false;
    for (var k in expected) {
        if (!Object.prototype.hasOwnProperty.call(echo, k)) return false;
        var ev = expected[k], rv = echo[k];
        var en = parseFloat(ev), rn = parseFloat(rv);
        if (!isNaN(en) && !isNaN(rn)) {
            if (Math.abs(en - rn) > 0.001) return false;
        } else if (String(ev) !== String(rv)) {
            return false;
        }
    }
    return true;
}

function pollForEcho(key, expected, targetEntityId, baseErrTs, baseErrVal) {
    var pollStart = Date.now();
    function tick() {
        var elapsed = Date.now() - pollStart;
        if (elapsed >= 30000) {
            showStatus('failed', 'Device did not confirm ' + key + ' update (timeout). It may be offline.');
            return;
        }
        self.ctx.attributeService.getEntityAttributes(targetEntityId, 'CLIENT_SCOPE', [key, 'pSetErr']).subscribe(
            function(attrs) {
                var receivedVal = null, errVal = null, errTs = 0;
                for (var i = 0; attrs && i < attrs.length; i++) {
                    var k = attrs[i].key !== undefined ? attrs[i].key : attrs[i].attributeKey;
                    if (k === key) receivedVal = attrs[i].value;
                    else if (k === 'pSetErr') { errVal = attrs[i].value; errTs = attrs[i].lastUpdateTs || 0; }
                }
                // Success wins: if the device echoed back what we sent, we are done,
                // regardless of any older pSetErr still sitting on the server.
                try {
                    var recv = typeof receivedVal === 'string' ? JSON.parse(receivedVal) : receivedVal;
                    if (recv && matchesPayload(expected, recv)) {
                        showStatus('success', 'Protection settings saved successfully.');
                        self.ctx.powerData = recv;
                        applyPowerToForm(recv);
                        setTimeout(function() { hideStatus(); }, 4000);
                        return;
                    }
                } catch (e) {}
                // Only treat pSetErr as a real rejection if it was reported AFTER this
                // save began (newer timestamp, or changed value when ts is unavailable).
                var errIsFresh = (errTs && baseErrTs) ? (errTs > baseErrTs) : (String(errVal) !== String(baseErrVal));
                if (errVal && errIsFresh) {
                    try {
                        var errObj = typeof errVal === 'string' ? JSON.parse(errVal) : errVal;
                        if (errObj && errObj.k === key) {
                            showStatus('failed', 'Device rejected ' + key + ': ' + errObj.m);
                            return;
                        }
                    } catch (e) {}
                }
                setTimeout(tick, 3000);
            },
            function() { setTimeout(tick, 3000); }
        );
    }
    setTimeout(tick, 3000);
}

function showStatus(cls, msg) {
    var $s = self.ctx.$container.find('#powerSaveStatus, #powerSaveStatusBottom');
    $s.removeClass('pending success failed').addClass(cls).text(msg).css('display', 'flex');
}

function hideStatus() {
    self.ctx.$container.find('#powerSaveStatus, #powerSaveStatusBottom').css('display', 'none');
}

function setFirmwareSupport(supported) {
    var $c = self.ctx.$container;
    if (supported) {
        $c.find('#pwFirmwareMsg').css('display', 'none');
        $c.find('#pwSettingsBody').css('display', '');
    } else {
        $c.find('#pwFirmwareMsg').css('display', 'block');
        $c.find('#pwSettingsBody').css('display', 'none');
    }
}

function loadAllData() {
    getTargetEntityId(function(targetEntityId) {
        if (!targetEntityId || !targetEntityId.id) {
            if (loadRetryCount < maxRetries) {
                loadRetryCount++;
                setTimeout(function() { loadAllData(); }, 500);
            }
            return;
        }
        self.ctx.attributeService.getEntityAttributes(targetEntityId, 'CLIENT_SCOPE', ['pSettings']).subscribe(
            function(attrs) {
                lastSuccessfulLoad = Date.now();
                var found = false;
                for (var i = 0; attrs && i < attrs.length; i++) {
                    var k = attrs[i].key !== undefined ? attrs[i].key : attrs[i].attributeKey;
                    if (k === 'pSettings' && attrs[i].value) {
                        found = true;
                        try {
                            var p = typeof attrs[i].value === 'string' ? JSON.parse(attrs[i].value) : attrs[i].value;
                            self.ctx.powerData = p;
                            applyPowerToForm(p);
                        } catch (e) { console.error('pSettings parse error', e); }
                    }
                }
                setFirmwareSupport(found);
            },
            function(err) { console.warn('Could not load CLIENT scope', err); }
        );
    });
}

function getTargetEntityId(callback) {
    if (self.ctx.cachedEntity && self.ctx.cachedEntity.id) {
        callback(self.ctx.cachedEntity);
        return;
    }
    var cb = function(entity) {
        if (entity && entity.id) self.ctx.cachedEntity = entity;
        callback(entity);
    };
    if (self.ctx.defaultSubscription && self.ctx.defaultSubscription.datasources) {
        var ds = self.ctx.defaultSubscription.datasources[0];
        if (ds) {
            if (ds.entity && ds.entity.id) { cb(ds.entity); return; }
            if (ds.entityAliasId && self.ctx.aliasController) {
                var info = self.ctx.aliasController.getInstantAliasInfo(ds.entityAliasId);
                if (info) {
                    if (info.currentEntity) { cb(info.currentEntity); return; }
                    if (info.resolvedEntities && info.resolvedEntities.length) { cb(info.resolvedEntities[0]); return; }
                }
                try {
                    var obs = self.ctx.aliasController.getAliasInfo(ds.entityAliasId);
                    if (obs && obs.subscribe) {
                        obs.subscribe(function(i) {
                            if (i && i.currentEntity) { cb(i.currentEntity); return; }
                            if (i && i.resolvedEntities && i.resolvedEntities.length) { cb(i.resolvedEntities[0]); return; }
                            fallbackEntity(cb);
                        }, function() { fallbackEntity(cb); });
                        return;
                    }
                } catch (e) {}
            }
        }
    }
    fallbackEntity(cb);
}

function fallbackEntity(callback) {
    if (self.ctx.dashboardCtx && self.ctx.dashboardCtx.stateController) {
        var s = self.ctx.dashboardCtx.stateController.getStateParams();
        if (s) {
            var fromCandidate = function(c) {
                if (!c) return null;
                if (c.id && c.entityType) return c;
                if (c.entityId) {
                    if (c.entityId.id && c.entityId.entityType) return c.entityId;
                    if (typeof c.entityId === 'string') return { id: c.entityId, entityType: 'DEVICE' };
                }
                return null;
            };
            var candidates = [s.targetEntityId, s.entityId, s.device_id];
            for (var i = 0; i < candidates.length; i++) {
                var e = fromCandidate(candidates[i]);
                if (e) { callback(e); return; }
            }
        }
    }
    if (self.ctx.datasources && self.ctx.datasources.length > 0) {
        var d = self.ctx.datasources[0];
        if (d.entity && d.entity.id) { callback(d.entity); return; }
    }
    if (self.ctx.aliasController && self.ctx.aliasController.resolvedAliases) {
        var resolved = self.ctx.aliasController.resolvedAliases;
        for (var key in resolved) {
            var alias = resolved[key];
            if (!alias) continue;
            if (alias.currentEntity && alias.currentEntity.id) { callback(alias.currentEntity); return; }
            if (alias.stateEntity && alias.stateEntity.id) { callback(alias.stateEntity); return; }
            if (alias.entity && alias.entity.id) { callback(alias.entity); return; }
            if (alias.resolvedEntities && alias.resolvedEntities.length && alias.resolvedEntities[0].id) {
                callback(alias.resolvedEntities[0]); return;
            }
        }
    }
    callback(null);
}

function startSessionKeepAlive() {
    visibilityHandler = function() {
        if (!document.hidden) {
            var since = Date.now() - lastSuccessfulLoad;
            if (since > SESSION_STALE_THRESHOLD) { loadRetryCount = 0; loadAllData(); }
        }
    };
    document.addEventListener('visibilitychange', visibilityHandler);
    sessionHealthTimer = setInterval(function() {
        if (document.hidden) return;
        var since = Date.now() - lastSuccessfulLoad;
        if (since > SESSION_STALE_THRESHOLD) { loadRetryCount = 0; loadAllData(); }
        else {
            getTargetEntityId(function(e) {
                if (!e) return;
                self.ctx.attributeService.getEntityAttributes(e, 'CLIENT_SCOPE', ['pSettings']).subscribe(
                    function() {}, function() { setTimeout(function() { loadRetryCount = 0; loadAllData(); }, 1000); }
                );
            });
        }
    }, SESSION_HEALTH_INTERVAL);
}

function stopSessionKeepAlive() {
    if (sessionHealthTimer) { clearInterval(sessionHealthTimer); sessionHealthTimer = null; }
    if (visibilityHandler) { document.removeEventListener('visibilitychange', visibilityHandler); visibilityHandler = null; }
}

self.onDataUpdated = function() { loadAllData(); };

self.onDestroy = function() {
    // Leaves no document-level listener behind when the dashboard moves on.
    closeHelpPanel();
    stopSessionKeepAlive();
};
